import sys
from collections import deque

d = sys.stdin.read().split()
r, c, k = int(d[0]), int(d[1]), int(d[2])
g = [[int(d[3 + i * c + j]) for j in range(c)] for i in range(r)]
seen = {(0, 0, 0)}
q = deque([(0, 0, 0, 0)])
ans = -1
while q:
    i, j, u, s = q.popleft()
    if (i, j) == (r - 1, c - 1):
        ans = s
        break
    for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
        if 0 <= ni < r and 0 <= nj < c:
            nu = u + g[ni][nj]
            if nu <= k and (ni, nj, nu) not in seen:
                seen.add((ni, nj, nu))
                q.append((ni, nj, nu, s + 1))
print(ans)

